    RCC->CCIPR &= ~RCC_CCIPR_I2C3SEL_Msk;
    RCC->CCIPR |= (2U << RCC_CCIPR_I2C3SEL_Pos);

    /* 2. Enable GPIOC and I2C3 peripheral clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* 3. Configure PC8 (I2C3_SCL) and PC9 (I2C3_SDA) as Alternate Function AF8 */
    GPIOC->MODER &= ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk);
    GPIOC->MODER |= (2U << GPIO_MODER_MODE8_Pos) | (2U << GPIO_MODER_MODE9_Pos); /* AF mode (10b) */

    /* Configure pins as Open-Drain (mandatory for I2C) */
    GPIOC->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    /* No internal pull-ups (rely on external level-shifter pull-ups) */
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk);

    /* High speed output */
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos) | (3U << GPIO_OSPEEDR_OSPEED9_Pos);

    /* Assign AF8 to PC8 and PC9 */
    GPIOC->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL8_Pos) | (0xFU << GPIO_AFRH_AFSEL9_Pos));
    GPIOC->AFR[1] |= (8U << GPIO_AFRH_AFSEL8_Pos) | (8U << GPIO_AFRH_AFSEL9_Pos);

    /* 4. Configure I2C3 timing while peripheral is disabled (PE = 0) */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /*
     * TIMINGR configuration for 100 kHz Standard-mode with f_I2CCLK = 16 MHz:
     * PRESC  = 3    (Prescaler = 4 -> t_PRESC = 250 ns)
     * SCLDEL = 4    (Setup time = (4 + 1) * 250 ns = 1250 ns)
     * SDADEL = 2    (Hold time  = 2 * 250 ns = 500 ns)
     * SCLH   = 0x0F (High time  = (15 + 1) * 250 ns = 4.0 us)
     * SCLL   = 0x13 (Low time   = (19 + 1) * 250 ns = 5.0 us)
     */
    I2C3->TIMINGR = (3U << I2C_TIMINGR_PRESC_Pos)   |
                    (4U << I2C_TIMINGR_SCLDEL_Pos)  |
                    (2U << I2C_TIMINGR_SDADEL_Pos)  |
                    (0x0FU << I2C_TIMINGR_SCLH_Pos) |
                    (0x13U << I2C_TIMINGR_SCLL_Pos);

    /* 5. Enable I2C3 controller peripheral */
    I2C3->CR1 |= I2C_CR1_PE;
}
