#include "stm32g4xx.h"

void i2c3_master_init(void)
{
    /* 1. Enable GPIOC peripheral clock on AHB2 */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;

    /* 2. Select HSI16 (16 MHz) as I2C3 kernel clock source (RCC_CCIPR: I2C3SEL = 10b) */
    RCC->CCIPR &= ~RCC_CCIPR_I2C3SEL_Msk;
    RCC->CCIPR |= (2U << RCC_CCIPR_I2C3SEL_Pos);

    /* 3. Enable I2C3 peripheral clock on APB1 */
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* 4. Configure PC8 (SCL) and PC9 (SDA) */
    /* Alternate function mode (10b) */
    GPIOC->MODER &= ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk);
    GPIOC->MODER |= (2U << GPIO_MODER_MODE8_Pos) | (2U << GPIO_MODER_MODE9_Pos);

    /* Open-drain output type */
    GPIOC->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    /* High speed output */
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos) | (3U << GPIO_OSPEEDR_OSPEED9_Pos);

    /* No internal pull-up / pull-down resistors (external pull-ups present on bus) */
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk);

    /* Route PC8 and PC9 to AF8 (I2C3_SCL, I2C3_SDA) via AFRH / AFR[1] */
    GPIOC->AFR[1] &= ~((0xFU << ((8U - 8U) * 4U)) | (0xFU << ((9U - 8U) * 4U)));
    GPIOC->AFR[1] |=  ((8U   << ((8U - 8U) * 4U)) | (8U   << ((9U - 8U) * 4U)));

    /* 5. Configure I2C3 timing: must be done while PE = 0 */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /* Standard-mode (100 kHz) timing for 16 MHz kernel clock (RM0440 Table 360):
     * PRESC = 3, SCLDEL = 4, SDADEL = 2, SCLH = 15 (0x0F), SCLL = 19 (0x13)
     */
    I2C3->TIMINGR = (3U    << I2C_TIMINGR_PRESC_Pos)  |
                    (4U    << I2C_TIMINGR_SCLDEL_Pos) |
                    (2U    << I2C_TIMINGR_SDADEL_Pos) |
                    (0x0FU << I2C_TIMINGR_SCLH_Pos)   |
                    (0x13U << I2C_TIMINGR_SCLL_Pos);

    /* 6. Enable I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;
}
