    FLASH->ACR &= ~FLASH_ACR_LATENCY_Msk;
    FLASH->ACR |= FLASH_ACR_LATENCY_4WS;

    /* Configure PLL: HSI16 (16 MHz) / M(4) * N(85) / R(2) = 170 MHz
