                   (3U << RCC_PLLCFGR_PLLM_Pos) |
                   (85U << RCC_PLLCFGR_PLLN_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* Enable PLL and wait for PLL ready */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    /* Switch system clock to PLL and wait for switch confirmation */
    RCC->CFGR &= ~RCC_CFGR_SW_Msk;
    RCC->CFGR |= RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS_Msk) != RCC_CFGR_SWS_PLL);

    /* ------------------------------------------------------------------------
     * 2. Peripheral Clock & Kernel Clock Configuration
     * ------------------------------------------------------------------------ */
    /* Enable GPIO port clocks: GPIOA for PA8 (TIM1), GPIOC for PC8/PC9 (I2C3) */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOCEN;

    /* Enable timer clock: TIM1 on APB2 */
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* Select HSI16 (16 MHz) as I2C3 kernel clock source (RCC_CCIPR: I2C3SEL = 10b) */
    RCC->CCIPR &= ~RCC_CCIPR_I2C3SEL_Msk;
    RCC->CCIPR |= (2U << RCC_CCIPR_I2C3SEL_Pos);

    /* Enable I2C3 peripheral clock on APB1 */
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

