    GPIOC->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9); /* Open-drain */

    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos) | (3U << GPIO_OSPEEDR_OSPEED9_Pos);
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk); /* External bus pull-ups */

    GPIOC->AFR[1] &= ~((0xFU << ((8U - 8U) * 4U)) | (0xFU << ((9U - 8U) * 4U)));
    GPIOC->AFR[1] |=  ((8U   << ((8U - 8U) * 4U)) | (8U   << ((9U - 8U) * 4U))); /* AF8 */

    /* ------------------------------------------------------------------------
     * 4. TIM1 Configuration (20 kHz, 25% Duty Cycle on PA8)
     * TIM1CLK = 170 MHz.
     * ARR = (170,000,000 / 20,000) - 1 = 8499.
     * CCR1 = (ARR + 1) * 25% = 8500 * 0.25 = 2125.
     * ------------------------------------------------------------------------ */
    TIM1->PSC  = 0U;
    TIM1->ARR  = 8499U;
    TIM1->CCR1 = 2125U;

    /* Channel 1: PWM Mode 1 (OC1M = 0110b), preload enabled (OC1PE = 1) */
    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Channel 1: Output enable, active high */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Auto-reload preload enable and Main Output Enable (MOE) for advanced timer */
    TIM1->CR1 |= TIM_CR1_ARPE;
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Force update event to transfer preload to active shadow registers */
    TIM1->EGR |= TIM_EGR_UG;
    TIM1->CR1 |= TIM_CR1_CEN;

    /* ------------------------------------------------------------------------
     * 5. I2C3 Configuration (Standard Mode 100 kHz, Controller)
     * Kernel clock = 16 MHz (HSI16 via CCIPR).
     * RM0440 Table 360: PRESC=3, SCLDEL=4, SDADEL=2, SCLH=15, SCLL=19.
     * ------------------------------------------------------------------------ */
    I2C3->CR1 &= ~I2C_CR1_PE; /* Must be disabled while writing TIMINGR */

    I2C3->TIMINGR = (3U    << I2C_TIMINGR_PRESC_Pos)  |
                    (4U    << I2C_TIMINGR_SCLDEL_Pos) |
                    (2U    << I2C_TIMINGR_SDADEL_Pos) |
                    (0x0FU << I2C_TIMINGR_SCLH_Pos)   |
                    (0x13U << I2C_TIMINGR_SCLL_Pos);

    /* Enable I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;

    /* ------------------------------------------------------------------------
     * 6. Main Loop
     * ------------------------------------------------------------------------ */
    while (1)
    {
    }
}
