```c
#include "stm32g4xx.h"

void tim1_pa8_pwm_init(void)
{
    /* 1. Enable GPIOA and TIM1 peripheral clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 as Alternate Function (AF6 = TIM1_CH1), high-speed push-pull [STM32G474_Datasheet p.73] */
    /* Clear MODER8 bits and set to 10 (Alternate Function mode) */
    GPIOA->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos);

    /* Output type: Push-Pull (reset state is 0, explicitly clear) */
    GPIOA->OTYPER &= ~GPIO_OTYPER_OT8;

    /* Output speed: High speed (10) */
    GPIOA->OSPEEDR &= ~GPIO_OSPEEDR_OSPEED8_Msk;
    GPIOA->OSPEEDR |= (2U << GPIO_OSPEEDR_OSPEED8_Pos);

    /* No pull-up, no pull-down */
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD8_Msk;

    /* Alternate function AF6 (TIM1_CH1) on PA8 (AFRH register, pin 8) [STM32G474_Datasheet p.73] */
    GPIOA->AFR[1] &= ~GPIO_AFRH_AFSEL8_Msk;
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos);

    /* 3. Configure TIM1 time-base for 20 kHz PWM
     * Timer clock = 170 MHz (APB2 timer clock with APB2 prescaler = 1)
     * Prescaler (PSC) = 0 -> timer counter clock = 170 MHz
     * Desired frequency = 20 kHz (period = 50 µs)
     * ARR = (170,000,000 / 20,000) - 1 = 8500 - 1 = 8499
     * Duty cycle = 25% -> CCR1 = 8500 * 0.25 = 2125
     */
    TIM1->PSC = 0;
    TIM1->ARR = 8499;
    TIM1->CCR1 = 2125;

    /* 4. Configure Channel 1 for PWM Mode 1 [STM32G474_RM0440 p.1251]
     * CC1S = 00 (Output)
     * OC1M[2:0] = 110 and OC1M[3] = 0 -> PWM Mode 1 (active while CNT < CCR1)
     * OC1PE = 1 (Output compare 1 preload enable)
     */
    TIM1->CCMR1 &= ~(TIM_CCMR1_CC1S_Msk | TIM_CCMR1_OC1M_Msk);
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 5. Configure Output Polarity and Enable Output [STM32G474_RM0440 p.1258]
     * CC1P = 0 (Active high)
     * CC1E = 1 (Enable Channel 1 output on PA8)
     */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* 6. Enable Auto-reload preload (ARPE) and set up-counting mode (CMS=00, DIR=0) */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* 7. Advanced-control timer: Enable Main Output (MOE) in BDTR [STM32G474_RM0440 p.1267] */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 8. Generate an update event to load preloaded registers (PSC, ARR, CCR1) */
    TIM1->EGR |= TIM_EGR_UG;

    /* 9. Start the counter */
    TIM1->CR1 |= TIM_CR1_CEN;
}
