```c
#include "stm32g4xx.h"

void i2c3_controller_init(void)
{
    /* 1. Select the independent kernel clock source for I2C3 in RCC_CCIPR [STM32G474_RM0440 p.323]
     * Select HSI16 (16 MHz) as I2C3 clock: I2C3SEL[1:0] = 10b (0x2)
     * (HSI16 is already active as the PLL source)
     */
    RCC->CCIPR &= ~RCC_CCIPR_I2C3SEL_Msk;
    RCC->CCIPR |= (2U << RCC_CCIPR_I2C3SEL_Pos);

    /* 2. Enable GPIOC and I2C3 peripheral clocks [STM32G474_RM0440 p.306, p.309] */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* 3. Configure PC8 (I2C3_SCL) and PC9 (I2C3_SDA) [STM32G474_Datasheet p.75]
     * - Alternate Function AF8 (I2C3)
     * - Open-drain output
     * - High speed
     * - Pull-up enabled (internal pull-ups active; external pull-ups to I2C rail recommended)
     */

    /* Alternate function mode (10b) on PC8 and PC9 */
    GPIOC->MODER &= ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk);
    GPIOC->MODER |= (2U << GPIO_MODER_MODE8_Pos) | (2U << GPIO_MODER_MODE9_Pos);

    /* Output type: Open-Drain (1b) */
    GPIOC->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    /* Output speed: High speed (10b) */
    GPIOC->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED8_Msk | GPIO_OSPEEDR_OSPEED9_Msk);
    GPIOC->OSPEEDR |= (2U << GPIO_OSPEEDR_OSPEED8_Pos) | (2U << GPIO_OSPEEDR_OSPEED9_Pos);

    /* Pull-up enabled (01b) */
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk);
    GPIOC->PUPDR |= (1U << GPIO_PUPDR_PUPD8_Pos) | (1U << GPIO_PUPDR_PUPD9_Pos);

    /* Alternate Function 8 (AF8) on PC8 and PC9 (AFRH register) */
    GPIOC->AFR[1] &= ~(GPIO_AFRH_AFSEL8_Msk | GPIO_AFRH_AFSEL9_Msk);
    GPIOC->AFR[1] |= (8U << GPIO_AFRH_AFSEL8_Pos) | (8U << GPIO_AFRH_AFSEL9_Pos);

    /* 4. Configure I2C3 peripheral
     * Ensure peripheral is disabled (PE = 0) before modifying TIMINGR [STM32G474_RM0440 p.1675]
     */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /* 5. Program I2C_TIMINGR for 100 kHz Standard-mode with f_I2CCLK = 16 MHz (HSI16)
     * Values from STM32G4 reference manual [STM32G474_RM0440 Table 360, p.1657]:
     * - PRESC  = 0x3 (t_PRESC = (3 + 1) * 62.5 ns = 250 ns)
     * - SCLDEL = 0x4 (t_SCLDEL = (4 + 1) * 250 ns = 1250 ns)
     * - SDADEL = 0x2 (t_SDADEL = 2 * 250 ns = 500 ns)
     * - SCLH   = 0x0F (t_SCLH = (15 + 1) * 250 ns = 4.0 µs)
     * - SCLL   = 0x13 (t_SCLL = (19 + 1) * 250 ns = 5.0 µs)
     *
     * Value: (0x3 << 28) | (0x4 << 20) | (0x2 << 16) | (0x0F << 8) | (0x13) = 0x30420F13
     */
    I2C3->TIMINGR = (0x3U << I2C_TIMINGR_PRESC_Pos)
                  | (0x4U << I2C_TIMINGR_SCLDEL_Pos)
                  | (0x2U << I2C_TIMINGR_SDADEL_Pos)
                  | (0x0FU << I2C_TIMINGR_SCLH_Pos)
                  | (0x13U << I2C_TIMINGR_SCLL_Pos);

    /* 6. Enable I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;
}
